/* ============================================================
   GENERAL PRACTICE: agreements used across commercial and
   corporate work, beyond any one type of transaction.
   ============================================================ */
const AGREED_FORM="in relation to a document, the form of that document agreed between the parties and initialled by or on their behalf for the purpose of identification";
const LIST_GT=["guarantees to {B} the punctual performance by the Principal Debtor of the Guaranteed Obligations;","undertakes that whenever the Principal Debtor does not pay any amount when due under or in connection with the Principal Agreement, {S} shall immediately on demand pay that amount as if it were the principal obligor; and","agrees, as an independent and primary obligation, to indemnify {B} immediately on demand against any loss or liability it suffers if any Guaranteed Obligation is or becomes unenforceable, invalid or illegal, the amount of that loss or liability being equal to the amount {B} would otherwise have been entitled to recover."];
const DEADLOCK_DEF="A “Deadlock” arises if a matter requiring the approval of the Board or of the shareholders has been considered at two consecutive duly convened meetings and has not been approved because of the opposition of the directors appointed by, or the votes of, one party.";
const ESCALATE="Either party may refer a Deadlock to the chief executives (or equivalent) of the parties, who shall try in good faith to resolve it within twenty (20) Business Days after the referral.";
const OFFER_FIRST="No party may transfer any Shares except in accordance with this clause {N}. A party wishing to transfer Shares shall first offer them to the other party at the price at which it is willing to sell. If the other party does not accept the offer in full within thirty (30) Business Days, the transferring party may, within the following three (3) months, sell those Shares to a bona fide third party at a price no lower than the offer price.";

/* ---------------- negotiable clauses ---------------- */
Object.assign(C,{
"gt-cap":{t:"Limit of the Guarantor's Liability",g:["guarantees"],
 d:"Whether the guarantor's exposure has a ceiling or an end date.",
 n:"Guarantees are construed strictly in the guarantor's favour where the wording is unclear, so state any cap and time limit in plain terms.",
 o:[
 ["Unlimited",-2,["{S}'s liability under this Deed is not limited in amount or in time."],
  "You can recover everything the principal debtor owes, for as long as it owes it.","Your exposure is open-ended and depends on a contract you do not control."],
 ["Capped amount",0,["{S}'s maximum aggregate liability under this Deed shall not exceed £[●], together with interest and costs payable under {R:*gt-pay}."],
  "The market position. Real security, at a level the guarantor's board can approve.","The market position. You know your maximum exposure."],
 ["Capped and time-limited",2,["{S}'s maximum aggregate liability under this Deed shall not exceed £[●].","{S} shall have no liability under this Deed unless {B} has made a written demand, giving reasonable details of the claim, within twelve (12) months after the expiry or termination of the Principal Agreement."],
  "The guarantee may run out before a claim surfaces.","A firm ceiling and a clear end date."]]},
"ht-excl":{t:"Exclusivity",g:["heads"],
 d:"Whether the seller must stop talking to other buyers while the buyer spends money on due diligence.",
 n:"A lock-out is enforceable only if it is for a defined period and supported by consideration (Walford v Miles [1992] UKHL 12). An open-ended duty to negotiate in good faith is not enforceable.",
 o:[
 ["Three months, with cost cover",-2,["In consideration of {B} incurring costs in investigating the Proposed Transaction, {S} undertakes that for three (3) months from the date of this letter (the “Exclusivity Period”) it shall not, and shall procure that none of its group companies, officers or advisers shall, solicit, encourage, negotiate or enter into any agreement with any person other than {B} in relation to any transaction similar to the Proposed Transaction, and shall promptly notify {B} of any approach.","If {S} breaches this clause {N}, it shall reimburse {B}'s reasonable costs incurred in connection with the Proposed Transaction, without prejudice to {B}'s other rights."],
  "Time to complete diligence without being outbid, and your costs back if the seller walks.","You are locked out of the market for three months, with a costs exposure."],
 ["Six weeks, ending early if terms change",0,["In consideration of {B} incurring costs in investigating the Proposed Transaction, {S} undertakes that for six (6) weeks from the date of this letter (the “Exclusivity Period”) it shall not solicit, negotiate or enter into any agreement with any person other than {B} in relation to the Proposed Transaction.","The Exclusivity Period shall end early if {B} notifies {S} that it no longer wishes to proceed, or proposes to reduce the consideration other than as a result of matters disclosed in due diligence."],
  "The market position. Enough time for focused diligence.","The market position. A short lock-out that ends if the buyer chips the price."],
 ["No exclusivity",2,["{S} is free to discuss the Proposed Transaction with other parties, but shall notify {B} before entering into any binding agreement with another person in relation to it."],
  "You could spend heavily on diligence and lose the deal to another bidder.","You keep competitive tension until signing."]]},
"stl-rel":{t:"Scope of Settlement",g:["settlement"],
 d:"Which claims the settlement wipes out.",
 n:"Under Bank of Credit and Commerce International SA v Ali [2001] UKHL 8, a release covers unknown claims only if the words make that clear. Fraud cannot be released by general words.",
 o:[
 ["The dispute only",-2,["With effect from receipt of the Settlement Sum in full, {B} releases {S} from all claims arising out of the Dispute.","Nothing in this Agreement releases any other claim, including any claim arising out of matters which are not the subject of the Dispute or which arise after the date of this Agreement."],
  "You settle the fight you are in and keep every other claim.","You pay, and may still face claims about the wider relationship."],
 ["Full and final, connected claims",0,["With effect from receipt of the Settlement Sum in full, this Agreement is in full and final settlement of, and each party releases the other and its group companies from, all claims which it has or may have arising out of or in connection with the Dispute or the contract to which it relates, whether known or unknown and whether or not in the contemplation of the parties at the date of this Agreement.","Nothing in this Agreement releases any claim for fraud or any claim to enforce this Agreement."],
  "The market position. A clean break on the subject matter, both ways.","The market position. A clean break on the subject matter, both ways."],
 ["All claims of any kind",2,["With effect from the date of this Agreement, {B} releases {S}, its group companies and its and their officers and employees from all claims of any nature which {B} has or may have against any of them, arising out of any matter up to the date of this Agreement, whether known or unknown and whether or not in the contemplation of the parties.","{B} shall not bring, and shall procure that no member of its group brings, any claim released by this clause {N}, and shall indemnify {S} against the costs of any such claim."],
  "You give up claims you may not yet know about, before you are paid.","Complete finality, immediately."]]},
"dt-rel":{t:"Release",g:["contract-changes"],
 d:"Whether either side can still sue for breaches before the contract ended.",
 o:[
 ["Customer released, keeps its own claims",-2,["With effect from the Termination Date, {S} releases {B} from all its obligations and liabilities under the Agreement, whether arising before or after the Termination Date.","Nothing in this Deed releases {S} from any liability for breach of the Agreement before the Termination Date."],
  "You walk away clean and keep your claims.","You give up your claims and keep your exposure."],
 ["Mutual release",0,["With effect from the Termination Date, each party releases the other from all its obligations and liabilities under or in connection with the Agreement, whether arising before or after the Termination Date and whether known or unknown.","This clause {N} does not release any obligation under this Deed or under the provisions of the Agreement listed in {R:*dt-surv}."],
  "The market position. A clean break both ways.","The market position. A clean break both ways."],
 ["Supplier released, keeps its own claims",2,["With effect from the Termination Date, {B} releases {S} from all its obligations and liabilities under the Agreement, whether arising before or after the Termination Date.","Nothing in this Deed releases {B} from any liability under the Agreement before the Termination Date, including for unpaid charges."],
  "You give up your claims and remain liable for the past.","You walk away clean and keep your claims."]]},
"da-war":{t:"Assignor's Warranties",g:["contract-changes"],
 d:"What the assignor promises about the contract being transferred.",
 o:[
 ["Full warranties",-2,[["{S} warrants to {B} that:",["the Agreement is in full force and effect and is the whole agreement between {S} and the Counterparty about its subject matter;","{S} has not assigned, charged or otherwise dealt with any of its rights under the Agreement;","the assignment does not breach the Agreement or require any consent which has not been obtained; and","no party is in breach of the Agreement and no notice of termination has been given or received."]]],
  "You know what you are buying, and have a claim if it is not.","You stand behind a contract you no longer control."],
 ["Title and capacity",0,["{S} warrants to {B} that it has not assigned, charged or otherwise dealt with any of its rights under the Agreement, and that it has full power to enter into this Deed."],
  "The market position. Clean title, though nothing about the contract's health.","The market position. You promise only what is within your knowledge and control."],
 ["Limited title guarantee only",2,["The assignment in {R:*da-assign} is made with limited title guarantee, and {S} gives no other warranty in relation to the Agreement."],
  "Very little comeback if the contract is in trouble.","Minimal exposure."]]},
"jv-board":{t:"Board and Management",g:["jv"],
 d:"Who appoints the directors and what makes a valid board meeting.",
 o:[
 ["Equal representation and quorum",-2,["Each party may appoint two (2) directors, regardless of its shareholding, and remove and replace any director it appoints.","The quorum for Board meetings is two directors, including at least one director appointed by each party. Each director has one vote and the chair has no casting vote."],
  "Equal say in the boardroom, despite your smaller stake.","Your majority stake does not translate into control of the board."],
 ["Proportionate representation, protected quorum",0,["Each party may appoint one (1) director for each twenty per cent. (20%) of the Shares it holds, and remove and replace any director it appoints.","The quorum for Board meetings is two directors, including at least one director appointed by each party. If a quorum is not present, the meeting shall be adjourned for five (5) Business Days, and at the adjourned meeting the directors present shall form a quorum."],
  "The market position. A seat at the table and a quorum that cannot be ignored, though not indefinitely.","The market position. Control in proportion to your stake, and meetings that cannot be blocked for ever."],
 ["Majority controls the board",2,["{S} may appoint a majority of the directors, and {B} may appoint one (1) director while it holds at least ten per cent. (10%) of the Shares.","The quorum for Board meetings is two directors, one of whom must be appointed by {S}. The chair shall be appointed by {S} and shall have a casting vote."],
  "Your influence is limited to the reserved matters.","You run the company."]]},
"jv-dead":{t:"Deadlock",g:["jv"],
 d:"What happens if the shareholders or their directors cannot agree.",
 n:"A shoot-out (Russian roulette) favours the party with readier access to funds. Escalation and mediation steps before any exit help preserve the relationship.",
 o:[
 ["Put option at fair value",-2,[DEADLOCK_DEF,ESCALATE,"If the Deadlock is not resolved, {B} may require {S} to buy all of {B}'s Shares at their fair value, determined by an independent accountant as between a willing buyer and a willing seller, with no discount for {B}'s minority holding."],
  "A guaranteed exit at full value if you are outvoted on a fundamental issue.","You may have to fund a buyout at a time not of your choosing."],
 ["Escalation, mediation, then status quo",0,[DEADLOCK_DEF,ESCALATE,"If the Deadlock is not resolved, the parties shall attempt to resolve it by mediation in accordance with the CEDR Model Mediation Procedure.","If the Deadlock remains unresolved thirty (30) Business Days after the referral to mediation, the proposal giving rise to it shall be treated as not approved, and the Company shall continue to operate in accordance with the current Business Plan."],
  "The market position. Nothing changes without your agreement.","The market position. A structured way to resolve disagreement without a forced sale."],
 ["Shoot-out",1,[DEADLOCK_DEF,ESCALATE,"If the Deadlock is not resolved, either party may serve a notice offering to buy all the other party's Shares at a price per Share specified in the notice. Within thirty (30) Business Days after receipt, the recipient must either sell its Shares at that price or buy all the server's Shares at the same price per Share, failing which it is treated as having elected to sell."],
  "A party with deeper pockets can use this to push you out.","A fast, final exit route that you are better placed to use."],
 ["Chair's casting vote",2,["The chair of the Board, who shall be appointed by {S}, shall have a casting vote on any matter that is not reserved under {R:sha-res}. No other deadlock procedure applies."],
  "You are outvoted on everything except the reserved matters.","No deadlock can arise on ordinary business."]]},
"jv-transfer":{t:"Transfer of Shares",g:["jv","covenants"],
 d:"When shareholders can sell, and whether one can force or follow the other's sale.",
 o:[
 ["Pre-emption and tag-along",-2,[OFFER_FIRST,"If {S} proposes to transfer Shares which would result in a third party holding more than fifty per cent. (50%) of the Shares, {B} may require the purchaser to buy all of {B}'s Shares on the same terms."],
  "You can always follow the majority out on the same terms.","A buyer for your stake must also buy the minority, which may deter buyers."],
 ["Pre-emption, tag and drag",0,[OFFER_FIRST,"If {S} proposes to transfer Shares which would result in a third party holding more than fifty per cent. (50%) of the Shares, {B} may require the purchaser to buy all of {B}'s Shares on the same terms.","If {S} accepts a bona fide arm's length offer for all its Shares, it may require {B} to sell all its Shares to the same purchaser on the same terms."],
  "The market position. You can follow any sale, but can also be required to join one.","The market position. You can deliver a buyer the whole company."],
 ["Drag-along only",2,[OFFER_FIRST,"If {S} accepts a bona fide offer for all its Shares, it may require {B} to sell all its Shares to the same purchaser on the same terms. {B} has no right to require any purchaser to buy its Shares."],
  "You can be forced to sell, but cannot insist on being included.","Full control over the exit."]]},
"inv-war":{t:"Warranties",g:["investment","warranties"],
 d:"What the company promises the investor about its business, and how much it can be made to pay.",
 n:"Damages against the company itself can be circular, because the investor is paid from a company it now partly owns. Investors therefore often ask the founders to give the warranties personally, capped at a multiple of salary.",
 o:[
 ["Full warranties, uncapped",-2,["The Company warrants to {B} that each of the statements in {SC:invwar} is true and accurate at the date of this Agreement and at Completion.","The Company's liability for breach of the Warranties is not limited in amount or time, save as provided by law."],
  "Full recourse if the business is not as described.","Unlimited exposure, paid out of the money just raised."],
 ["Disclosed, capped at the investment",0,["The Company warrants to {B} that each of the statements in {SC:invwar} is true and accurate at the date of this Agreement, except as fairly disclosed in the Disclosure Letter.","The Company's aggregate liability for breach of the Warranties shall not exceed the aggregate Subscription Price paid by {B}, and no claim may be brought unless notified to the Company within eighteen (18) months after Completion."],
  "The market position. A meaningful remedy for undisclosed problems.","The market position. Exposure limited to the money raised, for a limited period."],
 ["Capacity and title only",2,["The Company warrants to {B} only that it has the capacity and authority to enter into this Agreement and that the Subscription Shares will be validly issued and fully paid.","{B} acknowledges that it has made its own investigation of the Company and does not rely on any other statement."],
  "You invest on the strength of your own diligence alone.","Almost no warranty exposure."]]},
"asa-price":{t:"Conversion Price",g:["investment"],
 d:"The price at which the advance subscription turns into shares.",
 o:[
 ["Discount and valuation cap",-2,["The “Conversion Price” on a Qualifying Round shall be the lower of the price per share paid by investors in that round less a discount of twenty per cent. (20%), and the price per share implied by a pre-money valuation of £[●] (the “Valuation Cap”).","On a sale, listing or the Longstop Date, the Conversion Price shall be the price per share implied by the Valuation Cap."],
  "Rewarded for investing early, with a ceiling on the price you pay.","Early money can convert cheaply if the round is strong."],
 ["Discount only",0,["The “Conversion Price” on a Qualifying Round shall be the price per share paid by investors in that round, less a discount of twenty per cent. (20%).","On a sale, listing or the Longstop Date, the Conversion Price shall be the price per share implied by a pre-money valuation of £[●]."],
  "The market position. A reward for early risk.","The market position. A standard discount, with no cap on upside."],
 ["Round price, no discount",2,["The “Conversion Price” on a Qualifying Round shall be the price per share paid by investors in that round.","On a sale, listing or the Longstop Date, the Conversion Price shall be the price per share implied by a pre-money valuation of £[●], as determined by the board of the Company acting reasonably."],
  "No reward for taking risk early.","Early investors pay the same as everyone else."]]},
"cla-price":{t:"Conversion Price",g:["investment"],
 d:"The price at which the loan turns into shares.",
 o:[
 ["Discount and valuation cap",-2,["The “Conversion Price” on a Qualifying Round shall be the lower of the price per share paid by investors in that round less a discount of twenty per cent. (20%), and the price per share implied by a pre-money valuation of £[●].","On any other conversion, the Conversion Price shall be the price per share implied by a pre-money valuation of £[●]."],
  "Rewarded for lending early, with a ceiling on the price.","Early money can convert cheaply if the round is strong."],
 ["Discount only",0,["The “Conversion Price” on a Qualifying Round shall be the price per share paid by investors in that round, less a discount of twenty per cent. (20%).","On any other conversion, the Conversion Price shall be the price per share implied by a pre-money valuation of £[●]."],
  "The market position. A reward for early risk.","The market position. A standard discount, with no cap."],
 ["Round price",2,["The “Conversion Price” on a Qualifying Round shall be the price per share paid by investors in that round.","On any other conversion, the Conversion Price shall be determined by the board of the Company acting reasonably, by reference to fair market value."],
  "No reward for lending early.","The lender converts at the same price as new investors."]]},
"fr-terr":{t:"Territorial Protection",g:["franchising","competition"],
 d:"Whether the franchisee is protected from other franchisees and the franchisor in its area.",
 n:"Competition law limits how far territorial protection can go. In particular, preventing franchisees from responding to customers who approach them from outside their territory is a hardcore restriction under the Vertical Agreements Block Exemption Order 2022.",
 o:[
 ["Exclusive territory",-2,["During the Initial Term, {S} shall not operate, or grant any other person the right to operate, a business using the System or the Marks within the Territory."],
  "No competition from the brand in your area.","You cannot grow the network in that area, whatever its potential."],
 ["Protected while targets are met",0,["{S} shall not grant any other franchise for the Territory while {B} meets the minimum performance targets in the Operations Manual.","{S} may make online sales to customers in the Territory, and shall credit {B} with [●] per cent. of the net revenue from those sales."],
  "The market position. Protection you keep by performing.","The market position. Protection you can withdraw if the area underperforms."],
 ["No territorial protection",2,["The licence is non-exclusive. {S} may itself, or through others, operate businesses using the System anywhere, including within the Territory."],
  "Another franchisee could open next door.","Complete freedom to develop the network."]]},
"fr-post":{t:"Post-termination Restrictions",g:["franchising","covenants"],
 d:"Whether the franchisee can compete after the franchise ends.",
 n:"A post-term non-compete benefits from the Vertical Agreements Block Exemption Order 2022 only if it lasts no more than one year, is limited to the premises from which the franchisee operated and is indispensable to protect the franchisor's know-how. Wider restrictions must also pass the common law restraint of trade test.",
 o:[
 ["Confidentiality only",-2,["After termination or expiry, {B} shall cease to use the System and the Marks, but shall not otherwise be restricted from carrying on business."],
  "You can keep trading in your own name.","Your former franchisee can compete immediately, using what it learned."],
 ["One year, from the premises",0,["After termination or expiry, {B} shall cease to use the System and the Marks.","For twelve (12) months after termination or expiry, {B} shall not carry on a business competing with the Franchised Business from the Premises."],
  "The market position. A short restriction, limited to your old site.","The market position. Protection of the site and the know-how, in a form competition law accepts."],
 ["Two years, wider area",2,["After termination or expiry, {B} shall cease to use the System and the Marks.","For twenty-four (24) months after termination or expiry, {B} shall not be engaged in any business competing with the System within ten (10) miles of the Premises or of any other business operated under the System."],
  "You may be unable to work in your field locally for two years.","Strong protection, though at real risk of being unenforceable."]]},
"sp-excl":{t:"Category Exclusivity",g:["franchising"],
 d:"Whether the rights holder may also take money from the sponsor's competitors.",
 o:[
 ["Exclusive, with ambush protection",-2,["{S} shall not grant any sponsorship, supplier or promotional rights in relation to the Event to any competitor of {B} in the [●] category, and shall use reasonable endeavours to prevent ambush marketing by any such competitor at the Event."],
  "Your competitors are kept out of the event.","You give up income from a whole category."],
 ["Exclusive, existing deals excluded",0,["{S} shall not grant sponsorship rights in relation to the Event to any competitor of {B} in the [●] category, save under the arrangements listed in {SC:sprights} which are in place at the date of this Agreement."],
  "The market position. Category protection, with known exceptions.","The market position. Category exclusivity that respects deals already done."],
 ["Non-exclusive",2,["The Rights are non-exclusive. {S} may grant sponsorship rights to any other person, including competitors of {B}."],
  "A competitor could sponsor the same event.","Full freedom to sell sponsorship."]]},
"sp-morals":{t:"Reputation",g:["franchising","termination"],
 d:"Whether a party can walk away if the other damages its reputation.",
 o:[
 ["Sponsor may terminate on reasonable opinion",-2,["{B} may terminate this Agreement immediately by notice if {S}, the Event or any participant engaged by {S} does anything which, in {B}'s reasonable opinion, brings or is likely to bring {B} into disrepute.","On termination under this clause {N}, {S} shall refund the part of the Sponsorship Fee relating to the period after termination."],
  "You can exit quickly if the association becomes toxic.","Your fee depends on the sponsor's view of events you may not control."],
 ["Mutual, serious disrepute, cure period",0,["Either party may terminate this Agreement by notice if the other does anything which brings, or is reasonably likely to bring, the terminating party into serious public disrepute, and fails to take reasonable remedial steps within ten (10) Business Days after notice.","On termination under this clause {N}, {S} shall refund a fair proportion of the Sponsorship Fee for Rights not delivered."],
  "The market position. Protection for both brands, with an objective test.","The market position. Protection for both brands, with an objective test."],
 ["No reputation termination",2,["Neither party may terminate this Agreement on grounds of reputation, save under {R:tmb}."],
  "You may be tied to a damaging association.","Certainty of income."]]},
"col-ip":{t:"Ownership of Results",g:["ip"],
 d:"Who owns the intellectual property created in the project.",
 n:"Avoid joint ownership unless the parties agree how it will be exploited. Under the Patents Act 1977, a co-owner of a patent cannot license or assign it without the other co-owners' consent.",
 o:[
 ["Each party owns what it creates",-2,["Each party shall own the Foreground IPR created by its own personnel.","Each party grants the other a non-exclusive, royalty-free, perpetual licence to use its Foreground IPR for research and for the purposes of the Project, and shall negotiate in good faith a licence for commercial use on request."],
  "You keep what your team invents.","Results may be split in a way that makes them hard to exploit."],
 ["Lead party owns, with revenue share",0,["The Foreground IPR shall belong to {S}, and {B} assigns to {S}, by way of present assignment of future rights, all its right, title and interest in it.","{S} grants {B} a non-exclusive, royalty-free, perpetual licence to use the Foreground IPR for research and its internal purposes.","{S} shall pay {B} [●] per cent. of the net revenue it receives from licensing or otherwise exploiting the Foreground IPR."],
  "The market position. You share in the commercial upside.","The market position. Clear ownership, with a fair share for your partner."],
 ["Lead party owns outright",2,["The Foreground IPR shall belong to {S}, and {B} assigns to {S}, by way of present assignment of future rights, all its right, title and interest in it.","{S} grants {B} a non-exclusive, royalty-free licence to use the Foreground IPR for internal, non-commercial research only."],
  "You contribute to results you cannot commercialise.","Full ownership and freedom to exploit."]]},
"ds-liab":{t:"Liability for the Shared Data",g:["data"],
 d:"Who bears the cost if the sharing or use of the data breaches data protection law.",
 n:"Whether an indemnity can cover a regulatory fine is doubtful as a matter of public policy, so these options do not mention fines.",
 o:[
 ["Discloser covers unlawful disclosure",-2,["{S} shall indemnify {B} against all losses and costs arising from any claim that the disclosure of the Shared Data to {B} was unlawful, or that the data subjects were not properly informed of it."],
  "You are protected if the data should never have been shared with you.","You carry the risk of how your data was collected and disclosed."],
 ["Each party covers its own breaches",0,["Each party shall indemnify the other against all losses and costs arising from its own breach of this Agreement or of the Data Protection Legislation in relation to the Shared Data."],
  "The market position. Each side answers for its own conduct.","The market position. Each side answers for its own conduct."],
 ["Recipient covers its use, no warranty of accuracy",2,["{B} shall indemnify {S} against all losses and costs arising from {B}'s processing of the Shared Data.","{S} gives no warranty as to the accuracy or completeness of the Shared Data."],
  "You carry the risk of using data you did not collect.","Minimal exposure once the data has left you."]]},
"ref-fee":{t:"Introduction Fee",g:["franchising"],
 d:"How much the introducer earns and for how long.",
 o:[
 ["First year only",-2,["{B} shall pay {S} a fee of [●] per cent. of the Net Revenue received from each Introduced Client in the twelve (12) months after its first contract with {B}.","Fees are payable within thirty (30) days after the end of each quarter in which the Net Revenue is received, with a statement showing how they were calculated."],
  "A defined cost for each new client.","Your reward stops after a year, however valuable the client becomes."],
 ["Two years",0,["{B} shall pay {S} a fee of [●] per cent. of the Net Revenue received from each Introduced Client in the twenty-four (24) months after its first contract with {B}, including after the termination of this Agreement.","Fees are payable within thirty (30) days after the end of each quarter in which the Net Revenue is received, with a statement showing how they were calculated."],
  "The market position. A fair reward with a clear end.","The market position. A fair reward with a clear end."],
 ["For the life of the client",2,["{B} shall pay {S} a commission of [●] per cent. of all Net Revenue received from each Introduced Client for as long as it remains a client of {B}, including after the termination of this Agreement.","The commission is payable within thirty (30) days after the end of each quarter in which the Net Revenue is received, with a statement showing how it was calculated."],
  "An indefinite cost on your best clients.","Income for as long as the client stays."]]},
"bb-war":{t:"Seller's Warranties",g:["warranties"],
 d:"What the selling shareholder promises about the shares and its tax position.",
 o:[
 ["Title, capacity and tax information",-2,["{S} warrants that it is the sole legal and beneficial owner of the Sale Shares, free from all encumbrances, and has full power to sell them.","{S} shall provide such information as {B} reasonably requires to apply for clearance from HM Revenue & Customs on the tax treatment of the purchase, and warrants that it is accurate."],
  "Clean title, and support for the tax clearance.","More obligations around a tax treatment that benefits you."],
 ["Title and capacity",0,["{S} warrants that it is the sole legal and beneficial owner of the Sale Shares, free from all encumbrances, and has full power to sell them."],
  "The market position. The company receives clean title.","The market position. You promise what you control."],
 ["No warranties",2,["{S} sells the Sale Shares with such title as it has and gives no warranty in relation to them."],
  "No recourse if the shares are subject to a third party's rights.","Minimal exposure."]]},
"es-ref":{t:"Reference and Announcement",g:["employment-exits"],
 d:"What the employer will say about the employee after they leave.",
 o:[
 ["Factual confirmation only",-2,["{B} shall not be obliged to give any reference, but shall confirm {S}'s dates of employment and job title if asked by a prospective employer."],
  "No risk of a reference being challenged as misleading.","Little help in finding your next role."],
 ["Agreed reference",0,["{B} shall, on request from a prospective employer, give a reference in the form set out in Part 2 of {SC:esclaims}, and shall respond to any oral enquiry consistently with it."],
  "The market position. An agreed, accurate reference.","The market position. A reference you have seen and approved."],
 ["Agreed reference and announcement",2,["{B} shall, on request, give a reference in the form set out in Part 2 of {SC:esclaims}, and shall respond to oral enquiries consistently with it.","{B} shall announce {S}'s departure internally and externally in terms agreed with {S}, and shall instruct its directors not to make any derogatory statement about {S}."],
  "More commitments, including over what your directors say.","Control over how your departure is described."]]}
});

/* ---------------- standard clauses ---------------- */
Object.assign(F,{
"*gt-guar":{t:"Guarantee and Indemnity",g:["guarantees"],e:"The guarantor promises to pay if the debtor does not, and separately indemnifies the beneficiary. The indemnity matters: a guarantee falls away if the underlying obligation is void, but an indemnity does not.",p:[["In consideration of {B} entering into the Principal Agreement, {S} irrevocably and unconditionally:",LIST_GT]]},
"*gt-protect":{t:"Preservation of Rights",g:["guarantees"],e:"Under the rule in Holme v Brunskill (1878), a guarantor is released if the underlying contract is varied without its consent. This clause excludes that rule and other defences a guarantor would otherwise have.",p:[["The obligations of {S} under this Deed shall not be discharged, reduced or otherwise affected by any act, omission or circumstance which, but for this clause, might operate to release or reduce them, including:",["any time, waiver or consent granted to, or composition with, the Principal Debtor or any other person;","any amendment, variation, novation, supplement or replacement of the Principal Agreement, however fundamental;","any incapacity, insolvency or change in the constitution or ownership of the Principal Debtor; or","any invalidity, illegality or unenforceability of any obligation of any person under the Principal Agreement."]],"{S} waives any right it may have of first requiring {B} to proceed against or enforce any other right or security, or to claim payment from any other person, before claiming from {S} under this Deed.","Until all the Guaranteed Obligations have been irrevocably paid in full, {S} shall not exercise any right of subrogation, indemnity or contribution against the Principal Debtor, or claim in competition with {B} in the insolvency of the Principal Debtor."]},
"*gt-cont":{t:"Continuing Guarantee",g:["guarantees"],e:"The guarantee covers the final balance owed, not just the debt at the date it was signed, and survives payments that are later clawed back in an insolvency.",p:["This Deed is a continuing guarantee and indemnity and shall extend to the ultimate balance of the Guaranteed Obligations, regardless of any intermediate payment or discharge in whole or in part.","If any payment by the Principal Debtor, or any discharge given by {B}, is avoided or reduced as a result of insolvency or any similar event, the liability of {S} shall continue as if the payment, discharge or avoidance had not occurred."]},
"*gt-pay":{t:"Payments, Interest and Costs",g:["guarantees"],e:"Payments must be made in full, with interest on late payment and the beneficiary's enforcement costs.",p:["{S} shall make all payments under this Deed without set-off or counterclaim and free and clear of any deduction or withholding, save as required by law, in which case it shall pay such additional amount as will ensure that {B} receives the amount it would have received but for the deduction.","{S} shall pay interest on any amount demanded and unpaid, from the date of demand until payment, at the rate of four per cent. (4%) a year above the Bank of England base rate from time to time.","{S} shall pay on demand all costs and expenses, including legal fees, reasonably incurred by {B} in enforcing this Deed."]},
"*ht-terms":{t:"Principal Terms",g:["heads"],e:"The commercial deal in outline. Keep it short: detail belongs in the long form documents.",p:[["The principal terms of the Proposed Transaction are:",["consideration: £[●], payable in cash at completion [, subject to a [locked box] [completion accounts] adjustment];","structure: [●];","conditions: [any regulatory or third party approvals required];","key people: [●] to enter into new service agreements at completion;","warranties and indemnities: customary for a transaction of this kind, with limitations to be agreed; and","timetable: the parties intend to sign the Long Form Documents by [●]."]]]},
"*ht-dd":{t:"Due Diligence",g:["heads"],e:"Access for the buyer's investigation, and the conditions on which it will proceed.",p:["{S} shall give {B} and its advisers reasonable access to the books, records, premises and senior management of the business, and shall answer promptly and fully the reasonable enquiries of {B}, for the purposes of due diligence.","The Proposed Transaction is subject to {B} being satisfied with the results of its due diligence, the approval of its board and the agreement of the Long Form Documents."]},
"*ht-nonbind":{t:"Legal Effect",g:["heads"],e:"Makes clear which parts bind now and that nobody is committed to the deal until the full documents are signed.",p:["Save for {R:ht-excl}, {R:*ht-costs}, {R:conf}, this clause and {R:gl}, which are legally binding, this letter is not intended to create legal relations, and no party shall be obliged to proceed with the Proposed Transaction unless and until the Long Form Documents have been signed."]},
"*ht-costs":{t:"Costs",e:"Each side pays its own way, whether or not the deal happens.",p:["Each party shall bear its own costs in connection with the Proposed Transaction, whether or not it proceeds."]},
"*stl-pay":{t:"Settlement Payment",g:["settlement"],e:"What is paid, when, and what it covers.",p:["{S} shall pay the Settlement Sum to {B} within fourteen (14) days after the date of this Agreement, by electronic transfer to the account notified in writing by {B}'s solicitors.","The Settlement Sum is inclusive of interest and costs.","If {S} fails to pay the Settlement Sum in full when due, {B} may enforce this Agreement as a debt, and interest shall accrue on the unpaid amount at the rate applicable to judgment debts."]},
"*stl-proc":{t:"Proceedings",g:["settlement"],e:"Where there are proceedings, they are usually stayed by a Tomlin order, with the settlement terms in a confidential schedule, so that either side can return to court to enforce them.",p:["Within seven (7) days after receipt of the Settlement Sum, the parties shall file with the court a consent order in the agreed form staying the Proceedings on the terms of this Agreement, with no order as to costs.","Each party shall bear its own costs of the Dispute and the Proceedings."]},
"*stl-conf":{t:"Confidentiality of the Settlement",g:["settlement","confidentiality"],e:"Keeps the terms private while allowing the usual disclosures.",p:["Each party shall keep the terms of this Agreement, and the negotiations leading to it, confidential, save as required by law or regulation, to its professional advisers, auditors and insurers, or for the purpose of enforcing this Agreement.","Either party may state, if asked, that the Dispute has been resolved to the parties' mutual satisfaction."]},
"*dv-var":{t:"Variation",g:["contract-changes"],e:"Records the changes and when they take effect. If the original contract says how it may be varied, follow that procedure exactly: Rock Advertising v MWB Business Exchange Centres [2018] UKSC 24.",p:["With effect from [●] (the “Variation Date”), the Agreement shall be varied as set out in {SC:varn}.","Each party confirms that it has complied with any requirements in the Agreement for the variation of its terms."]},
"*dv-cont":{t:"Continuation",g:["contract-changes"],e:"Everything not changed stays as it was.",p:["Save as varied by this Deed, the Agreement shall continue in full force and effect. References in the Agreement to the Agreement shall be read as references to it as varied by this Deed.","This Deed does not affect any right or liability of either party under the Agreement which accrued before the Variation Date."]},
"*dt-term":{t:"Termination",g:["contract-changes"],e:"Fixes the end date and the practical steps on exit.",p:["The Agreement shall terminate with effect from [●] (the “Termination Date”).","On or before the Termination Date, each party shall return to the other, or securely destroy, all property and confidential information of the other in its possession, and {B} shall pay all undisputed sums due to {S} for the period before the Termination Date."]},
"*dt-surv":{t:"Surviving Provisions",g:["contract-changes"],e:"Some terms, such as confidentiality, should outlive the contract.",p:["The provisions of the Agreement relating to confidentiality, intellectual property, limitation of liability, governing law and jurisdiction shall continue in force after the Termination Date in accordance with their terms."]},
"*da-assign":{t:"Assignment",g:["contract-changes"],e:"Transfers the benefit of the contract. The burden cannot be assigned: if the assignee is to take on the obligations, the other party must agree to a novation.",p:["In consideration of the payment of £[●] by {B} to {S} (receipt of which {S} acknowledges), {S} assigns absolutely to {B} all its rights, title, interest and benefit in, to and under the Agreement, with effect from [●] (the “Assignment Date”).","{S} shall remain responsible for all its obligations under the Agreement, and for all liabilities arising under it before the Assignment Date."]},
"*da-notice":{t:"Notice of Assignment",g:["contract-changes"],e:"Written notice to the other party makes this a legal assignment under section 136 of the Law of Property Act 1925, so the assignee can sue in its own name. Check first that the contract permits assignment.",p:["{S} shall, on the date of this Deed, give written notice of the assignment to the Counterparty in the form set out in {SC:noticeassign}, and shall use reasonable endeavours to procure that the Counterparty acknowledges it.","{S} shall promptly pay to {B} any amount it receives under the Agreement after the Assignment Date, and pending payment shall hold it on trust for {B}."]},
"*jv-form":{t:"Establishment of the Company",g:["jv"],e:"Each party's share subscription, and what the company does.",p:["On the date of this Agreement, each party shall subscribe for the number of Shares set out against its name in {SC:jvcap}, so that the parties hold the issued share capital of the Company in the proportions set out there.","The parties shall procure that the Company carries on the Business, and no other business, in accordance with the Business Plan and on sound commercial principles."]},
"*jv-fund":{t:"Further Funding",g:["jv"],e:"No party has to put in more money unless it agrees, and any agreed funding is shared in proportion.",p:["The parties intend that the Company shall meet its working capital requirements from its own resources and external borrowing, without recourse to the parties.","No party shall be obliged to provide further finance or any guarantee to or for the Company. Any further funding agreed by the parties shall be provided by them in proportion to their shareholdings, on the same terms."]},
"*jv-plan":{t:"Business Plan",g:["jv"],e:"How the annual plan is set, and what happens if it cannot be agreed.",p:["The Board shall prepare a draft Business Plan for each financial year and submit it to the parties not less than two (2) months before that year begins. Each Business Plan shall take effect when approved by both parties.","Until a new Business Plan is approved, the Company shall operate in accordance with the previous Business Plan, with its budget increased in line with inflation."]},
"*sub-subscr":{t:"Subscription",g:["investment"],e:"The investor's commitment to buy the new shares, and the company's approvals needed to issue them.",p:["Subject to the terms of this Agreement, {B} shall subscribe for the Subscription Shares at the Subscription Price, and the Company shall allot and issue them to {B} credited as fully paid.","Before Completion, the Company shall procure that its shareholders pass all resolutions required to authorise the allotment of the Subscription Shares, to disapply any rights of pre-emption under section 561 of the Companies Act 2006 and its articles of association, and to adopt the Articles."]},
"*sub-compl":{t:"Completion",g:["investment"],e:"The exchange of money for shares, and the filings that follow.",p:[["Completion shall take place on the date of this Agreement, or such later date as the parties agree, when:",["{B} shall pay the aggregate Subscription Price to the Company's bank account;","the Company shall allot and issue the Subscription Shares, enter {B} in its register of members and deliver a share certificate to {B}; and","the Company shall deliver to {B} certified copies of the resolutions referred to in {R:*sub-subscr}."]],"The Company shall file the return of allotment and the Articles at Companies House within the statutory time limits."]},
"*sub-use":{t:"Use of Proceeds",g:["investment"],e:"The money is used as presented to the investor.",p:["The Company shall use the subscription monies only for the purposes set out in the business plan provided to {B} before the date of this Agreement and for its general working capital."]},
"*sub-gov":{t:"Investor Rights",g:["investment"],e:"A board seat, regular financial information and a veto over fundamental decisions.",p:[["For so long as {B} holds any Investor Shares:",["{B} may appoint one person as a director of the Company (the “Investor Director”), and remove and replace any person so appointed;","the Company shall provide {B} with monthly management accounts within twenty (20) Business Days after the end of each month, audited annual accounts within ninety (90) days after the end of each financial year, and its draft annual budget before the start of each financial year; and","the Company shall not, without {B}'s prior written consent, issue any shares, amend the Articles, sell all or substantially all of its business or assets, borrow more than £[●] in aggregate, or make any material change to the nature of its business."]]]},
"*eis":{t:"Tax Reliefs",g:["investment"],e:"Investors in early-stage companies often rely on SEIS or EIS income tax relief. The company must keep to the scheme rules for three years. Obtain advance assurance from HM Revenue & Customs before the round.",p:["The Company shall use all reasonable endeavours to ensure that the Subscription Shares qualify for relief under [the Seed Enterprise Investment Scheme in Part 5A] [the Enterprise Investment Scheme in Part 5] of the Income Tax Act 2007, and shall submit the required compliance statement to HM Revenue & Customs promptly once it is able to do so.","The Company shall not, without {B}'s prior written consent, take or omit to take any action which would cause that relief to be withdrawn or reduced."]},
"*asa-pay":{t:"Advance Subscription",g:["investment"],e:"The investor pays now for shares to be issued later.",p:["{B} shall pay the Subscription Amount to the Company within five (5) Business Days after the date of this Agreement, in consideration of the Company's obligation to issue shares to {B} under this Agreement."]},
"*asa-conv":{t:"Issue of Shares",g:["investment"],e:"When the advance turns into shares, and that it can never be repaid.",p:[["The Company shall issue shares to {B} for the Subscription Amount, credited as fully paid, at the Conversion Price, on the earliest of:",["completion of a Qualifying Round;","immediately before completion of a sale of the Company or a listing of its shares; and","the Longstop Date."]],"Shares issued on a Qualifying Round shall be of the class issued in that round. In any other case they shall be ordinary shares.","The Subscription Amount bears no interest, and {B} has no right to its repayment in any circumstances."]},
"*asa-eis":{t:"Tax Reliefs",g:["investment"],e:"HM Revenue & Customs treats an advance subscription as eligible for SEIS or EIS only if, among other things, it has a longstop date no more than six months away, cannot be refunded, carries no interest and cannot be varied or transferred. Check the current HMRC guidance before signing.",p:["The parties intend that the shares issued under this Agreement qualify for relief under the Seed Enterprise Investment Scheme or the Enterprise Investment Scheme, and the Company shall use reasonable endeavours to obtain and maintain that relief.","This Agreement may not be varied, terminated or assigned, and the Subscription Amount may not be repaid."]},
"*cla-adv":{t:"The Loan",g:["investment"],e:"The amount lent and its purpose.",p:["{B} shall advance the Loan to the Company within five (5) Business Days after the date of this Agreement. The Company shall use the Loan for its general working capital."]},
"*cla-int":{t:"Interest",g:["investment"],e:"Interest usually rolls up and converts with the loan rather than being paid in cash.",p:["Interest shall accrue on the Loan at eight per cent. (8%) a year, calculated daily and compounded annually, and shall be paid on repayment or converted together with the Loan."]},
"*cla-conv":{t:"Conversion",g:["investment"],e:"The loan converts into shares in the next funding round, or the lender chooses on a sale.",p:["On completion of a Qualifying Round, the Loan and accrued interest shall automatically convert into shares of the class issued in that round at the Conversion Price.","If a sale of the Company or a listing of its shares occurs before conversion, {B} may elect by notice to the Company either to convert the Loan and accrued interest at the Conversion Price immediately before completion of that sale or listing, or to be repaid twice the amount of the Loan together with accrued interest."]},
"*cla-repay":{t:"Maturity and Default",g:["investment"],e:"What happens if no funding round occurs, and when the lender can demand its money back early.",p:["If the Loan has not converted by the Maturity Date, {B} may by notice require the Company either to repay the Loan and accrued interest within ten (10) Business Days, or to convert them into ordinary shares at the price per share implied by a pre-money valuation of £[●].","The Loan and accrued interest shall become immediately repayable on demand if the Company becomes insolvent, enters into any insolvency proceeding or ceases to carry on business, or fails to pay any sum due under this Agreement within ten (10) Business Days after its due date."]},
"*fr-grant":{t:"Grant of Franchise",g:["franchising"],e:"The right to run the business under the brand and system, and the option to renew.",p:["{S} grants {B} a licence for the Initial Term to operate the Franchised Business at [●] (the “Premises”), using the System and the Marks, in accordance with this Agreement.","{B} may renew this Agreement for a further term of five (5) years on {S}'s then current form of franchise agreement, if it is not in material breach and gives {S} not less than six (6) months' notice before the end of the Initial Term."]},
"*fr-fees":{t:"Fees and Records",g:["franchising"],e:"The initial fee, the ongoing fee and the marketing contribution, and the records that support them.",p:[["{B} shall pay {S}:",["an initial fee of £[●] on the date of this Agreement, which is not refundable;","a management services fee of [●] per cent. of Gross Revenue for each month, within ten (10) days after the end of that month; and","a contribution of [●] per cent. of Gross Revenue to the marketing fund administered by {S}, at the same time."]],"{B} shall keep complete and accurate accounts of the Franchised Business, deliver a monthly statement of Gross Revenue with each payment, and allow {S} to inspect and audit its records on reasonable notice."]},
"*fr-sys":{t:"Operation of the Franchised Business",g:["franchising"],e:"The franchisee follows the system. Requirements to buy from the franchisor must stay within competition law.",p:["{B} shall operate the Franchised Business strictly in accordance with the System and the Operations Manual, and shall maintain the standards of quality, service and appearance it prescribes.","{B} shall buy the products and equipment specified in the Operations Manual only from {S} or suppliers approved by it, to the extent that competition law permits.","{S} may inspect the Premises and the Franchised Business at any reasonable time."]},
"*fr-train":{t:"Training and Support",g:["franchising"],e:"What the franchisor provides in return for its fees.",p:["{S} shall provide initial training to {B} and its manager before the Franchised Business opens, and such continuing support and advice as it provides generally to its franchisees."]},
"*sp-grant":{t:"Grant of Rights",g:["franchising"],e:"What the sponsor receives.",p:["{S} grants {B} the Rights for the Term, as [the official [●] partner] of the Event.","{S} shall deliver the Rights to at least the standard described in {SC:sprights}, and shall display the Sponsor Marks as set out there."]},
"*sp-fee":{t:"Sponsorship Fee",g:["franchising"],e:"Payment by instalments, with an adjustment if rights are not delivered.",p:["{B} shall pay the Sponsorship Fee in the instalments set out in {SC:sprights}, each within thirty (30) days after receipt of a valid VAT invoice.","If any Right is not delivered, the parties shall agree in good faith either a reduction in the Sponsorship Fee or equivalent alternative rights."]},
"*sp-marks":{t:"Use of Marks",g:["franchising","ip"],e:"Each side may use the other's brand only as approved.",p:["Each party grants the other a non-exclusive, royalty-free licence for the Term to use its marks solely to exercise the Rights or perform this Agreement, subject to the owner's prior approval of each use and its brand guidelines. All goodwill arising from that use shall accrue to the owner of the marks."]},
"*sp-cancel":{t:"Cancellation of the Event",g:["franchising","force-majeure"],e:"Who bears the loss if the event does not happen.",p:["If the Event is cancelled, {S} shall refund the part of the Sponsorship Fee paid for Rights not delivered, less any costs reasonably and irrecoverably incurred in delivering them, unless the parties agree to transfer the Rights to a replacement event."]},
"*col-proj":{t:"The Project",g:["ip"],e:"Each party does its part and bears its own costs. Research carries no guarantee of results.",p:["Each party shall carry out the tasks allocated to it in the Project Plan with reasonable skill and care, and shall provide the personnel, facilities and contributions set out there.","Each party shall bear its own costs of the Project, save as set out in the Project Plan.","No party gives any warranty that the Project will achieve any particular result."]},
"*col-gov":{t:"Steering Committee",e:"A joint committee runs the project.",p:["The parties shall establish a steering committee with two (2) representatives from each party, which shall meet at least quarterly to monitor the Project and agree any changes to the Project Plan. Decisions of the steering committee require the agreement of both parties."]},
"*col-bg":{t:"Background IPR",g:["ip"],e:"What each party brings stays its own.",p:["Each party retains ownership of its Background IPR. Each party grants the other a non-exclusive, royalty-free licence to use its Background IPR during the Project Period, solely to carry out the Project."]},
"*col-liab":{t:"Limitation of Liability",g:["liability"],e:"Research collaborations rarely involve payment between the parties, so liability is usually limited to a fixed sum.",p:["Nothing in this Agreement limits or excludes either party's liability for death or personal injury caused by its negligence, for fraud, or for any other liability which cannot be limited or excluded by law.","Subject to clause {N}.1, neither party shall be liable to the other for any loss of profit or any indirect or consequential loss arising under or in connection with this Agreement, and each party's total liability under or in connection with this Agreement shall not exceed £[●]."]},
"*col-pub":{t:"Publication",g:["ip","confidentiality"],e:"Academic partners need to publish. This gives the other side time to protect inventions first.",p:["A party wishing to publish any results of the Project shall give the other party at least thirty (30) days' notice, with a copy of the proposed publication. The other party may require a delay of up to sixty (60) further days to allow protection of any Foreground IPR, or the removal of its Confidential Information."]},
"*ds-purpose":{t:"Purpose and Roles",g:["data"],e:"Each party is a separate controller, using the data only for the agreed purpose.",p:["{S} shall share the Shared Data with {B} for the Agreed Purpose only. Each party is an independent controller of the Shared Data it processes.","{B} shall not process the Shared Data for any purpose other than the Agreed Purpose without {S}'s prior written consent and a lawful basis for doing so."]},
"*ds-lawful":{t:"Lawful Processing",g:["data"],e:"The Information Commissioner's data sharing code of practice, made under the Data Protection Act 2018, sets out what a good data sharing agreement covers.",p:["Each party shall comply with the Data Protection Legislation in relation to the Shared Data.","{S} shall ensure that it has a lawful basis for disclosing the Shared Data, and that the data subjects have been given the information about the sharing required by Articles 13 and 14 of the UK GDPR. {B} shall ensure that it has a lawful basis for its own processing of the Shared Data."]},
"*ds-rights":{t:"Data Subject Rights",g:["data"],e:"Each controller answers requests about the data it holds, with help from the other.",p:["Each party shall be responsible for responding to requests from data subjects in relation to the Shared Data it holds, and shall give the other reasonable assistance, at its own cost, in responding to any request which relates to the other's processing."]},
"*ds-sec":{t:"Security and Breaches",g:["data"],e:"Appropriate security, and quick notice of any breach.",p:["Each party shall implement appropriate technical and organisational measures to protect the Shared Data, as required by Article 32 of the UK GDPR.","Each party shall notify the other without undue delay, and in any event within forty-eight (48) hours, after becoming aware of a Personal Data Breach involving the Shared Data, and the parties shall co-operate in dealing with it."]},
"*ds-transfer":{t:"International Transfers",g:["data"],e:"Transfers outside the UK must meet the UK GDPR's transfer rules.",p:["{B} shall not transfer the Shared Data outside the United Kingdom unless the transfer complies with Chapter V of the UK GDPR."]},
"*ds-end":{t:"Duration and Return of Data",g:["data"],e:"How the sharing ends and what happens to the data.",p:["This Agreement shall continue until [●], unless terminated earlier by either party on thirty (30) days' written notice.","On termination, {B} shall, at {S}'s option, return or securely delete the Shared Data, save to the extent that it is required by law to keep it."]},
"*ref-appt":{t:"Appointment",g:["franchising"],e:"The introducer only introduces. It cannot bind the company, which keeps it outside the rules for commercial agents.",p:["{B} appoints {S} on a non-exclusive basis to introduce prospective customers to {B}.","{S} is not an agent of {B}, has no authority to bind {B} or to make any representation on its behalf, and shall not hold itself out as having that authority."]},
"*ref-proc":{t:"Introductions",g:["franchising"],e:"How an introduction is registered, so there is no argument later about who introduced whom.",p:["{S} shall notify each proposed introduction to {B} in writing, with the prospective customer's name and contact details. {B} may accept or decline it in its absolute discretion within ten (10) Business Days. A proposed introduction of a person who was already a customer of, or in discussions with, {B} shall not be accepted.","{B} is under no obligation to enter into any contract with an Introduced Client."]},
"*ref-abc":{t:"Anti-bribery",g:["franchising"],e:"A company commits an offence under section 7 of the Bribery Act 2010 if a person associated with it, such as an introducer, bribes someone to win business for it, unless it has adequate procedures to prevent bribery.",p:["{S} shall comply with the Bribery Act 2010 and with {B}'s anti-bribery policy as notified to it, and shall not offer or give any payment or other advantage to any person to induce an introduction.","{S} shall disclose its relationship with {B} to each prospective customer where required by law or by that customer's own policies."]},
"*flowdown":{t:"Back-to-back Obligations",e:"Passes the main contract's requirements down to the subcontractor. Pay-when-paid clauses are generally ineffective in construction contracts under the Housing Grants, Construction and Regeneration Act 1996, so this form is not designed for construction work.",p:["{S} acknowledges that {B} provides services to its customer (the “Customer”) under a contract dated [●] (the “Head Contract”), the relevant provisions of which {B} has disclosed to {S}.","{S} shall perform the Services so as to enable {B} to comply with its obligations under the Head Contract, and shall not do anything that would cause {B} to be in breach of it.","{S} shall comply with the provisions of the Head Contract listed in {SC:svc} as if they applied to {S}, with references to the supplier read as references to {S}.","{B} shall pay the Charges in accordance with this Agreement whether or not it has been paid by the Customer."]},
"*ned-appt":{t:"Appointment",g:["employment-exits"],e:"A non-executive director holds an office, not a job.",p:["{B} appoints {S} as a non-executive director of {B} with effect from [●], for an initial term of three (3) years, subject to re-election at any general meeting at which {B}'s articles of association require it.","{S} is not an employee of {B}, and this Agreement is not a contract of employment."]},
"*ned-time":{t:"Time Commitment",g:["employment-exits"],e:"The time expected, so both sides understand the role.",p:["{S} shall devote such time as is necessary for the proper performance of the role, which {B} anticipates will be at least [●] days a year, including attendance at [●] Board meetings, the annual general meeting and the meetings of any committee of which {S} is a member."]},
"*ned-fee":{t:"Fees and Expenses",g:["employment-exits"],e:"Directors' fees are taxed as income of an office holder.",p:["{B} shall pay {S} a fee of £[●] a year, payable monthly in arrears, subject to deduction of any income tax and national insurance contributions required by law, and shall reimburse expenses reasonably and properly incurred in the role.","{S} shall not participate in any bonus or share incentive scheme of {B} unless the Board decides otherwise."]},
"*ned-duties":{t:"Duties and Conflicts",g:["employment-exits"],e:"The statutory duties of every director apply in full to non-executives.",p:["{S} shall comply with the duties of a director under Part 10 of the Companies Act 2006, including the duty to avoid conflicts of interest under section 175 and to declare interests in proposed and existing transactions under sections 177 and 182.","{S} shall disclose to the Board all other directorships and significant commitments, and shall obtain the Board's agreement before accepting any further appointment which might conflict with the role."]},
"*ned-conf":{t:"Confidentiality",g:["employment-exits","confidentiality"],e:"What a director learns stays confidential.",p:["{S} shall not, during or after the appointment, use or disclose any confidential information of {B} or its group, save in the proper performance of the role or as required by law.","{S} shall comply with {B}'s policies on dealing in its securities and on inside information, where they apply."]},
"*ned-ins":{t:"Insurance and Indemnity",g:["employment-exits"],e:"Protection for the director, within what company law allows.",p:["{B} shall maintain directors' and officers' liability insurance covering {S} during the appointment and for six (6) years after it ends, and shall indemnify {S} to the extent permitted by sections 232 to 234 of the Companies Act 2006."]},
"*ned-end":{t:"Termination",g:["employment-exits"],e:"How the appointment ends. Shareholders can always remove a director by ordinary resolution.",p:["Either party may terminate the appointment on three (3) months' written notice. The appointment shall terminate immediately, without compensation, if {S} is not re-elected, is removed under {B}'s articles of association or by resolution under section 168 of the Companies Act 2006, or becomes disqualified from acting as a director.","On termination, {S} shall resign from any office in {B}'s group and return all property of {B} and its group."]},
"*bb-cond":{t:"Conditions",g:["investment"],e:"A buyback must be approved by special resolution, without the selling shareholder's votes counting, and funded from distributable profits.",p:["This Agreement is conditional on its terms being approved by a special resolution of {B} under section 694 of the Companies Act 2006 before Completion. The resolution shall be passed without reliance on the votes attached to the Sale Shares, as section 695 of that Act requires.","{B} shall fund the purchase out of its distributable profits [or the proceeds of a fresh issue of shares made for the purpose], in accordance with section 692 of the Companies Act 2006."]},
"*bb-sale":{t:"Sale and Purchase",g:["investment"],e:"The shares are bought back free from any third party rights.",p:["Subject to {R:*bb-cond}, {S} shall sell, and {B} shall buy, the Sale Shares for the Consideration, free from all encumbrances."]},
"*bb-compl":{t:"Completion",g:["investment"],e:"The shares must be paid for in full on purchase, and the buyback reported to Companies House.",p:["Completion shall take place immediately after the passing of the resolution referred to in {R:*bb-cond}, when {S} shall deliver the share certificate for the Sale Shares, or an indemnity for any lost certificate, and {B} shall pay the Consideration in full in cash, as section 691 of the Companies Act 2006 requires.","{B} shall, within twenty-eight (28) days after Completion, deliver to the registrar of companies the return required by section 707 of the Companies Act 2006, and shall pay any stamp duty due on it."]},
"*bb-tax":{t:"Tax Treatment",g:["investment"],e:"A buyback payment is normally taxed as a dividend unless the capital treatment conditions are met. Clearance from HMRC gives certainty.",p:["The parties acknowledge that the payment of the Consideration may be treated as a distribution for tax purposes unless the conditions in Chapter 3 of Part 23 of the Corporation Tax Act 2010 are met. {B} may apply to HM Revenue & Customs for advance clearance, and {S} shall provide the information reasonably required for that purpose."]},
"*es-term":{t:"Termination of Employment",g:["employment-exits"],e:"The leaving date and the normal final pay.",p:["{S}'s employment shall terminate on the Termination Date. {B} shall pay {S} their salary and contractual benefits up to the Termination Date in the usual way, together with pay in lieu of any accrued but untaken holiday, subject to deduction of income tax and national insurance contributions."]},
"*es-pay":{t:"Termination Payment",g:["employment-exits"],e:"Up to £30,000 of a termination payment can be paid free of income tax if the conditions in the Income Tax (Earnings and Pensions) Act 2003 are met. Post-employment notice pay is always taxable.",p:["Subject to {S} complying with this Agreement, {B} shall pay {S} the Termination Payment as compensation for the termination of their employment, within fourteen (14) days after the later of the Termination Date and {B}'s receipt of this Agreement signed by {S} together with the Adviser's certificate.","{B} shall pay the first £30,000 of the Termination Payment without deduction of tax, to the extent permitted by sections 401 to 404 of the Income Tax (Earnings and Pensions) Act 2003, and the balance subject to deduction of income tax and national insurance contributions. Any post-employment notice pay, within the meaning of sections 402A to 402E of that Act, shall be paid separately subject to deductions.","{S} shall be responsible for, and shall indemnify {B} against, any further income tax or employee's national insurance contributions due on the Termination Payment."]},
"*es-waive":{t:"Waiver of Claims",g:["employment-exits"],e:"The heart of the agreement. Statutory claims can only be waived if the conditions in section 203(3) of the Employment Rights Act 1996 and section 147(3) of the Equality Act 2010 are met.",p:["{S} accepts the payments under this Agreement in full and final settlement of all claims they have or may have against {B} or any Group Company, or their officers or employees, arising out of their employment or its termination, whether under statute, contract, common law or otherwise, in the United Kingdom or elsewhere, including the claims listed in Part 1 of {SC:esclaims} (the “Specified Claims”).","This clause does not waive any claim for personal injury of which {S} is not aware at the date of this Agreement, any claim in relation to accrued pension rights, or any claim to enforce this Agreement.","The parties agree that the conditions regulating settlement agreements under section 203(3) of the Employment Rights Act 1996, section 147(3) of the Equality Act 2010 and the other legislation listed in Part 1 of {SC:esclaims} are satisfied."]},
"*es-conf":{t:"Confidentiality and Statements",g:["employment-exits","confidentiality"],e:"Confidentiality cannot prevent whistleblowing or reporting crime. This clause says so expressly.",p:["{S} shall keep the terms of this Agreement confidential, save to their immediate family, their professional advisers, HM Revenue & Customs, or as required by law.","Nothing in this Agreement prevents {S} from making a protected disclosure within the meaning of section 43A of the Employment Rights Act 1996, reporting a criminal offence to a law enforcement agency or regulator, or co-operating with any such agency or regulator.","{S} shall not make any derogatory statement about {B} or any Group Company."]},
"*es-adv":{t:"Independent Advice",g:["employment-exits"],e:"The employee must take advice from a named, insured, relevant independent adviser, or the waiver of statutory claims is ineffective.",p:["{S} warrants that they have received independent legal advice from the Adviser on the terms and effect of this Agreement, and in particular its effect on their ability to pursue the Specified Claims, and that the Adviser has confirmed that there is in force a contract of insurance, or an indemnity provided for members of a profession or professional body, covering the risk of a claim against the Adviser in respect of loss arising from that advice.","{B} shall contribute up to £[●] (plus VAT) towards {S}'s legal fees for that advice, payable directly to the Adviser's firm."]},
"*es-ret":{t:"Property and Offices",g:["employment-exits"],e:"The practical tidying up on exit.",p:["{S} shall return all property of {B} and any Group Company by the Termination Date, and shall resign from any office held in any Group Company without claim for compensation."]}
});

/* ---------------- agreement kinds ---------------- */
const SHA_CO={"Company":"[●] Limited, a company incorporated in England and Wales with registered number [●]","Shares":"shares of any class in the capital of the Company","Board":"the board of directors of the Company","Articles":"the articles of association of the Company from time to time"};
Object.assign(K,{
gtee:{first:"S",tail:["gl"],deed:true,doc:"Deed",
 rec:["{B} has entered, or proposes to enter, into the Principal Agreement with the Principal Debtor.","{S} has agreed to guarantee the obligations of the Principal Debtor under the Principal Agreement on the terms of this Deed."],
 defs:{"Principal Debtor":"[●] Limited, a company incorporated in England and Wales with registered number [●]","Principal Agreement":"the [●] agreement dated [●] between {B} and the Principal Debtor, as amended, varied, supplemented or replaced from time to time","Guaranteed Obligations":"all present and future obligations and liabilities of the Principal Debtor to {B} under or in connection with the Principal Agreement, whether actual or contingent"},
 order:["*gt-guar","gt-cap","*gt-protect","*gt-cont","*gt-pay"],
 note:"A guarantee must be in writing and signed by the guarantor. Executing it as a deed avoids any question about consideration. Check that giving the guarantee is in the guarantor's commercial interest and is approved by its board."},
heads:{first:"S",tail:["gl"],doc:"letter",boil:["*varw","*sev","*3p","*notice","*cpart"],
 rec:["The parties are in discussions about the Proposed Transaction.","This letter records the principal terms on which the parties intend to proceed. Except as stated in {R:*ht-nonbind}, it is not legally binding."],
 defs:{"Proposed Transaction":"the proposed [acquisition by {B} of the entire issued share capital of [●] Limited]","Long Form Documents":"the definitive agreements to implement the Proposed Transaction","Confidential Information":"all information about the Proposed Transaction, the parties and the business concerned which is disclosed by or on behalf of one party to the other in connection with the Proposed Transaction"},
 order:["*ht-terms","*ht-dd","ht-excl","*ht-costs","conf","*ht-nonbind"],
 note:"Keep heads of terms short and clearly non-binding, save for exclusivity, confidentiality and costs. Heads that go into detail invite arguments that a binding contract was made."},
stl:{first:"B",tail:["gl"],
 rec:["A dispute has arisen between the parties, which is the subject of the Proceedings.","The parties have agreed to settle the Dispute on the terms of this Agreement, without any admission of liability."],
 defs:{"Dispute":"the dispute between the parties in relation to [●], as described in [the particulars of claim in the Proceedings]","Proceedings":"the proceedings in the [High Court of Justice, Business and Property Courts of England and Wales] between the parties with claim number [●]","Settlement Sum":"£[●]","agreed form":AGREED_FORM},
 order:["*stl-pay","stl-rel","*stl-proc","*noadmit","*stl-conf"],
 note:"Agree the scope of the release with care: a release of unknown claims cannot be undone. If no proceedings have been issued, delete the proceedings clause and the definition."},
dvar:{first:"B",tail:["gl"],deed:true,doc:"Deed",boil:["*sev","*3p","*notice","*cpart"],
 rec:["The parties are parties to the Agreement.","The parties wish to vary the Agreement on the terms of this Deed."],
 defs:{"Agreement":"the [●] agreement dated [●] between {B} and {S} [, as previously varied on [●]]"},
 order:["*dv-var","*dv-cont"],sch:["varn"],
 note:"A variation for no new consideration should be made by deed. Check the original contract's variation clause and any consents needed, for example from a guarantor."},
dterm:{first:"B",tail:["gl"],deed:true,doc:"Deed",boil:["*sev","*3p","*notice","*cpart"],
 rec:["The parties are parties to the Agreement.","The parties have agreed to terminate the Agreement, and to settle their obligations under it, on the terms of this Deed."],
 defs:{"Agreement":"the [●] agreement dated [●] between {B} and {S}"},
 order:["*dt-term","dt-rel","*dt-surv"],
 note:"Check whether any guarantee, licence or other document depends on the agreement being terminated, and deal with it at the same time."},
dassign:{first:"S",tail:["gl"],deed:true,doc:"Deed",boil:["*sev","*3p","*notice","*cpart"],
 rec:["{S} is a party to the Agreement with the Counterparty.","{S} has agreed to assign the benefit of the Agreement to {B} on the terms of this Deed."],
 defs:{"Agreement":"the [●] agreement dated [●] between {S} and the Counterparty","Counterparty":"[●] Limited, the other party to the Agreement"},
 order:["*da-assign","da-war","*da-notice"],sch:["noticeassign"],
 note:"Only the benefit of a contract can be assigned. If the assignee is to take over the obligations too, use a novation signed by all three parties."},
jv:{first:"S",tail:["dr","gl"],
 rec:["The parties have agreed to establish the Company as a joint venture company to carry on the Business.","The parties have agreed to regulate the affairs of the Company, and their relationship as its shareholders, on the terms of this Agreement."],
 defs:Object.assign({"Business":"the business of [●]","Business Plan":"the business plan of the Company for each financial year, adopted in accordance with {R:*jv-plan}"},SHA_CO),
 order:["*jv-form","*jv-fund","jv-board","sha-res","*jv-plan","jv-dead","jv-transfer","*conflict","conf"],sch:["jvcap"],
 note:"Most joint ventures also need new articles of association consistent with this agreement. Consider competition clearance and any merger control filing if both parents are active in the joint venture's market."},
sub:{first:"S",tail:["gl"],
 rec:["The Company is a private company limited by shares incorporated in England and Wales.","{B} has agreed to subscribe for the Subscription Shares, and the Company has agreed to issue them, on the terms of this Agreement."],
 defs:Object.assign({"Subscription Shares":"[●] [Series A preferred] shares of £[●] each in the capital of the Company","Investor Shares":"the Subscription Shares and any other Shares held by {B}","Subscription Price":"£[●] for each Subscription Share","Completion":"completion of the subscription in accordance with {R:*sub-compl}","Disclosure Letter":"the letter dated the date of this Agreement from the Company to {B} disclosing exceptions to the Warranties","Warranties":"the statements set out in {SC:invwar}","agreed form":AGREED_FORM},SHA_CO,{"Articles":"the articles of association of the Company in the agreed form, to be adopted at Completion"}),
 order:["*sub-subscr","*sub-compl","inv-war","sha-pre","*sub-use","*sub-gov","conf"],sch:["invwar"],
 note:"Founders usually join the agreement as warrantors and as parties to the shareholder provisions, and the articles carry the share rights. Check whether any existing investor consents or pre-emption waivers are needed."},
asa:{first:"S",tail:["gl"],boil:["*entire","*sev","*3p","*notice","*cpart"],
 rec:["The Company is a private company limited by shares incorporated in England and Wales.","{B} wishes to pay in advance for shares in the Company, to be issued on the terms of this Agreement."],
 defs:Object.assign({"Subscription Amount":"£[●]","Qualifying Round":"the next issue of equity shares by the Company after the date of this Agreement which raises not less than £[●] in aggregate, excluding the Subscription Amount","Longstop Date":"the date falling six (6) months after the date of this Agreement"},SHA_CO),
 order:["*asa-pay","*asa-conv","asa-price","*asa-eis"],
 note:"Advance subscription agreements are designed for SEIS and EIS investors, so they carry no interest and cannot be repaid. If the investor wants repayment rights, use a convertible loan instead."},
cla:{first:"S",tail:["gl"],
 rec:["The Company is a private company limited by shares incorporated in England and Wales.","{B} has agreed to lend money to the Company, to be repaid or converted into shares on the terms of this Agreement."],
 defs:Object.assign({"Loan":"the principal amount of £[●] advanced under this Agreement, or so much of it as is outstanding","Qualifying Round":"the next issue of equity shares by the Company after the date of this Agreement which raises not less than £[●] in aggregate, excluding the Loan","Maturity Date":"the date falling eighteen (18) months after the date of this Agreement"},SHA_CO),
 order:["*cla-adv","*cla-int","*cla-conv","cla-price","*cla-repay"],
 note:"A convertible loan is debt until it converts, so it ranks ahead of shareholders on insolvency but does not qualify for SEIS or EIS relief."},
fran:{first:"S",tail:["dr","gl"],
 rec:["{S} has developed the System and owns the Marks.","{B} wishes to operate a business using the System and the Marks, and {S} has agreed to grant a franchise on the terms of this Agreement."],
 defs:{"System":"the system developed by {S} for the operation of [●] businesses, including its methods, standards, know-how and the Operations Manual","Operations Manual":"{S}'s confidential operations manual for the System, as amended by {S} from time to time","Marks":"the trade marks and names listed in {SC:frmarks}","Territory":"[●]","Gross Revenue":"all revenue of the Franchised Business, excluding VAT","Franchised Business":"the business operated by {B} under this Agreement","Initial Term":"the period of [five (5)] years from the date of this Agreement"},
 order:["*fr-grant","fr-terr","*fr-fees","*fr-sys","*fr-train","conf","fr-post","tmb","asg"],sch:["frmarks"],
 note:"There is no franchise-specific legislation in England and Wales, but many franchisors follow the British Franchise Association's code of ethics. Give the franchisee time to take independent advice before signing."},
spons:{first:"S",tail:["dr","gl"],
 rec:["{S} owns or controls the commercial rights in the Event.","{B} wishes to sponsor the Event, and {S} has agreed to grant it the Rights, on the terms of this Agreement."],
 defs:{"Event":"[●]","Rights":"the rights described in {SC:sprights}","Sponsor Marks":"the trade marks and logos of {B} notified to {S} for use under this Agreement","Sponsorship Fee":"£[●] (exclusive of VAT)","Term":"the period from the date of this Agreement until [●]"},
 order:["*sp-grant","sp-excl","*sp-fee","*sp-marks","sp-morals","*sp-cancel","conf","tmb"],sch:["sprights"],
 note:"Check that the rights holder actually controls the rights it is granting, such as venue signage and broadcast placements, which are often held by others."},
collab:{first:"S",tail:["dr","gl"],
 rec:["The parties wish to collaborate on the Project, combining their expertise and resources.","The parties have agreed to do so on the terms of this Agreement."],
 defs:{"Project":"the research and development project described in {SC:colplan}","Project Plan":"the plan for the Project set out in {SC:colplan}, as varied by the steering committee","Project Period":"the period from the date of this Agreement until [●]","Background IPR":"Intellectual Property Rights owned by or licensed to a party before the date of this Agreement, or developed independently of the Project","Foreground IPR":"Intellectual Property Rights arising from the Project","Intellectual Property Rights":IPR_DEF},
 order:["*col-proj","*col-gov","*col-bg","col-ip","*col-pub","conf","*col-liab","tmb"],sch:["colplan"],
 note:"Where a university is a party, expect its standard positions on publication and academic use. Where public funding is involved, check the funder's conditions on IP and subsidy control."},
dsa:{first:"S",tail:["gl"],
 rec:["{S} holds the Shared Data, and {B} wishes to receive it for the Agreed Purpose.","The parties have agreed the terms on which the Shared Data will be shared, as independent controllers."],
 defs:{"Shared Data":"the personal data described in {SC:dsdetails}","Agreed Purpose":"[●], as described in {SC:dsdetails}","Data Protection Legislation":DPL_DEF,"UK GDPR":UKGDPR_DEF,"Personal Data Breach":"has the meaning given to it in the UK GDPR"},
 order:["*ds-purpose","*ds-lawful","*ds-rights","*ds-sec","ds-liab","*ds-transfer","*ds-end"],sch:["dsdetails"],
 note:"Use this where both parties decide how and why they use the data. Where one party processes data only on the other's instructions, use a data processing agreement instead. The Data (Use and Access) Act 2025 amends the UK GDPR in stages, so check the current position."},
ref:{first:"S",tail:["gl"],
 rec:["{S} has contacts with businesses that may wish to buy {B}'s products or services.","{B} has agreed to pay {S} for introductions it accepts, on the terms of this Agreement."],
 defs:{"Introduced Client":"a person introduced by {S} whose introduction {B} has accepted under {R:*ref-proc}","Net Revenue":"the fees actually received by {B} from an Introduced Client, excluding VAT, disbursements and expenses","Initial Term":"the period of [one (1)] year from the date of this Agreement"},
 order:["*ref-appt","*ref-proc","ref-fee","*ref-abc","conf","tmb","asg"],
 note:"Introducers in regulated sectors, such as financial services or legal services, may need authorisation, or may be prohibited from receiving fees. Check before using this for a regulated business."},
ned:{first:"B",tail:["gl"],ind:"S",
 rec:[],
 defs:{"Board":"the board of directors of {B}"},
 order:["*ned-appt","*ned-time","*ned-fee","*ned-duties","*ned-conf","*ned-ins","*ned-end"],
 note:"Non-executive appointments are usually documented by letter. For listed companies, reflect the UK Corporate Governance Code and the company's board evaluation and independence policies."},
buyback:{first:"S",tail:["gl"],
 rec:["{S} is the registered holder of the Sale Shares.","{B} has agreed to buy back the Sale Shares from {S}, and {S} has agreed to sell them, under Chapter 4 of Part 18 of the Companies Act 2006 and on the terms of this Agreement."],
 defs:{"Sale Shares":"[●] [ordinary] shares of £[●] each in the capital of {B}, registered in the name of {S}","Consideration":"£[●]","Completion":"completion of the sale and purchase of the Sale Shares under {R:*bb-compl}"},
 order:["*bb-cond","*bb-sale","*bb-compl","bb-war","*bb-tax"],
 note:"A copy of the agreement must be available for inspection before the resolution is passed and kept at the registered office afterwards. Payment out of capital follows a different procedure, with a directors' statement and auditor's report."},
empset:{first:"B",tail:["gl"],ind:"S",
 rec:[],
 defs:{"Termination Date":"[●]","Termination Payment":"£[●]","Adviser":"[●] of [●], a relevant independent adviser within the meaning of section 203(3A) of the Employment Rights Act 1996","Group Company":"{B}, any subsidiary or holding company of {B}, and any subsidiary of any such holding company"},
 order:["*es-term","*es-pay","*es-waive","es-ref","*es-conf","*es-adv","*es-ret"],sch:["esclaims"],
 note:"A settlement agreement waives statutory employment claims only if it is in writing, relates to particular claims, and the employee has taken advice from an identified, insured, relevant independent adviser."}
});

