Object.assign(SCHED,{
 varn:{t:"Variations",e:"Each change to the agreement, clause by clause.",kinds:["dvar"],always:true,gen:()=>[{tbl:{cols:["Clause of the Agreement","Variation"],w:[26,74],rows:[["[●]","[Delete clause [●] and replace it with: “[●]”]"],["[●]","[Insert a new clause [●]: “[●]”]"]]}}]},
 noticeassign:{t:"Form of Notice of Assignment",e:"The notice that makes the assignment legal. Send it on signing.",kinds:["dassign"],gen:()=>[
  {p:"To: [Counterparty], [address]",n:""},{p:"Date: [●]",n:""},
  {p:"We give you notice that, by a deed of assignment dated [●], we have assigned absolutely to [Assignee] all our rights, title, interest and benefit in, to and under the agreement dated [●] between you and us.",n:"1"},
  {p:"From the date of this notice, please make all payments due to us under that agreement to [Assignee], at the account it notifies to you, and deal with [Assignee] in respect of our rights under it. Our obligations to you under that agreement are not affected.",n:"2"},
  {p:"Please acknowledge receipt of this notice by signing and returning the enclosed copy.",n:"3"}]},
 jvcap:{t:"Share Capital",e:"Each party's initial shareholding.",kinds:["jv"],always:true,gen:ctx=>[{tbl:{cols:["Shareholder","Number of Shares","Class","Subscription price"],w:[34,22,20,24],rows:[[ctx.a.p[1],"[●]","Ordinary","£[●]"],[ctx.a.p[0],"[●]","Ordinary","£[●]"]]}}]},
 invwar:{t:"Warranties",e:"The statements the company makes about itself. Keep them proportionate to the size and stage of the business.",kinds:["sub"],gen:()=>[{p:["The Company warrants that:",listify(["it is duly incorporated and has full power and authority to enter into and perform this Agreement","the information about its share capital in the Disclosure Letter is complete and accurate, and no person has any right to the issue of any shares other than as disclosed","its latest accounts give a true and fair view of its financial position, and there has been no material adverse change since their date","it is not involved in any litigation, and none is threatened","it owns, or has the right to use, all intellectual property it needs to carry on its business","it has complied in all material respects with applicable laws, including data protection law","each employee and consultant who has created intellectual property for it has assigned that intellectual property to it","it has paid all tax due and filed all returns required","no insolvency proceedings have been commenced in relation to it, and it is able to pay its debts as they fall due","the business plan provided to the Investor was prepared with due care, and the assumptions in it are reasonable"])],n:"1"}]},
 frmarks:{t:"The Marks",e:"The trade marks and names licensed to the franchisee, with registration numbers."},
 sprights:{t:"The Rights and Fee Instalments",e:"The sponsorship rights in detail, the standard of delivery, the payment schedule and any existing arrangements excluded from exclusivity."},
 colplan:{t:"The Project Plan",e:"The project's objectives, each party's tasks and contributions, milestones and budget."},
 dsdetails:{t:"Details of the Data Sharing",e:"What data is shared, why, on what lawful basis, and for how long.",kinds:["dsa"],always:true,gen:()=>[{tbl:{cols:["Item","Details"],w:[34,66],rows:[["Agreed Purpose","[●]"],["Categories of data subject","[●]"],["Categories of personal data","[●]"],["Special category or criminal offence data","[None] [●]"],["Lawful basis for disclosure","[●]"],["Lawful basis for the recipient's processing","[●]"],["Retention period","[●]"],["Method of transfer and security","[●]"]]}}]},
 esclaims:{t:"Specified Claims, Reference and Adviser's Certificate",e:"The claims waived, the agreed reference and the adviser's signed certificate.",kinds:["empset"],always:true,gen:()=>[
  {h:"Part 1",s:"Specified Claims"},
  {p:["The Specified Claims are claims for or in respect of:",listify(["unfair dismissal, a statutory redundancy payment, unlawful deductions from wages and detriment, under the Employment Rights Act 1996","discrimination, harassment, victimisation or equal pay, under the Equality Act 2010","holiday pay or rest breaks, under the Working Time Regulations 1998","the national minimum wage, under the National Minimum Wage Act 1998","information and consultation, under the Transfer of Undertakings (Protection of Employment) Regulations 2006","breach of contract or wrongful dismissal"])],n:"1"},
  {h:"Part 2",s:"Agreed Reference"},
  {p:"[Employee] was employed by [Employer] from [●] to [●]. Their job title at the end of their employment was [●].",n:""},
  {h:"Part 3",s:"Adviser's Certificate"},
  {p:"I, [name], of [firm], confirm that I am a relevant independent adviser within the meaning of section 203(3A) of the Employment Rights Act 1996; that I have advised [Employee] on the terms and effect of the agreement to which this certificate is attached, and in particular its effect on their ability to pursue the Specified Claims; and that there is in force a contract of insurance, or an indemnity provided for members of a profession or professional body, covering the risk of a claim against me in respect of loss arising from that advice.",n:""},
  {p:"Signed: .............................. Date: [●]",n:""}]}
});

/* ---------------- guides ---------------- */
GUIDES.push(
{id:"heads",t:"Heads of terms, exclusivity and the deal process",cat:"Corporate",s:"What heads of terms are for, what should bind, and when an exclusivity agreement is enforceable.",b:[
"Heads of terms record the main commercial points before lawyers draft the full documents. They focus minds and flush out deal breakers early, but they are not a contract to do the deal.",
{h:"What should bind"},
"Usually only confidentiality, exclusivity, costs and governing law. Say so clearly. Heads that are detailed and silent on their status can be found to be a binding agreement.",
{h:"Exclusivity"},
"A buyer will not spend heavily on diligence if the seller can sell to someone else. A lock-out is enforceable if it lasts for a fixed period and the buyer gives something for it, such as agreeing to incur costs. A promise to negotiate in good faith, with no end date, is not enforceable.",
{k:"Agree heads quickly. Time spent perfecting them is better spent on the full documents."}],c:["ht-excl"]},
{id:"investment",t:"Early-stage investment: subscriptions, advance subscriptions and convertibles",cat:"Corporate",s:"The main ways to invest in a private company, and the points investors and founders argue about.",b:[
"A priced round uses a subscription agreement and new articles. Before a priced round, companies often raise money through an advance subscription agreement or a convertible loan, which turn into shares at the next round.",
{h:"Advance subscriptions"},
"Designed for investors claiming SEIS or EIS relief. The money cannot be repaid and carries no interest, and it must convert by a longstop date. HMRC's conditions are strict, so follow the current guidance.",
{h:"Convertible loans"},
"A loan with interest that converts into shares, or is repaid if no round happens. It gives the investor more protection, but does not qualify for SEIS or EIS.",
{h:"What gets negotiated"},
"The discount and valuation cap on conversion, the warranties and who gives them, anti-dilution protection, the investor's veto rights and its board seat.",
{k:"Founders: watch the veto list. A long list of investor consents can slow every decision the business makes."}],c:["inv-war","asa-price","cla-price","sha-pre"]},
{id:"jv",t:"Joint ventures and shareholders' agreements",cat:"Corporate",s:"How shareholders share control, resolve deadlock and exit.",b:[
"A shareholders' agreement sits alongside the articles and governs how the owners run the company together. It is private, unlike the articles, and can give rights to particular shareholders.",
{h:"Control"},
"Board seats, quorum and reserved matters decide who really controls the company. A minority shareholder's protection usually comes from the reserved matters it can veto.",
{h:"Deadlock"},
"In a 50:50 venture, deadlock is the central risk. Options run from escalation and mediation to shoot-outs and winding up. A shoot-out favours the party with readier access to funds.",
{h:"Exit"},
"Pre-emption keeps shares within the existing owners. Tag-along lets a minority follow a sale. Drag-along lets a majority deliver the whole company to a buyer.",
{k:"Make sure the articles say the same thing. Third parties, including buyers, rely on the articles."}],c:["jv-board","jv-dead","jv-transfer","sha-res"]},
{id:"guarantees",t:"Guarantees and indemnities from third parties",cat:"Finance",s:"How a guarantee works, why guarantors are often released by accident, and the protections beneficiaries use.",b:[
"A guarantee is a promise to answer for someone else's debt. The guarantor's liability depends on the underlying obligation: if that is void or released, the guarantee falls away too.",
{h:"Why an indemnity as well"},
"An indemnity is a primary obligation. It survives even if the underlying debt is unenforceable, which is why most guarantees include one.",
{h:"Accidental release"},
"A guarantor can be discharged if the main contract is varied without its consent, or time is given to the debtor. Well-drafted guarantees exclude these defences expressly.",
{h:"Formalities"},
"A guarantee must be in writing and signed by the guarantor. Executing it as a deed avoids arguments about consideration.",
{k:"Ask the guarantor to sign any later variation of the main contract too. It costs nothing and removes the argument."}],c:["gt-cap"]},
{id:"settlement",t:"Settling disputes",cat:"Disputes",s:"How to make a settlement final, private and enforceable.",b:[
"Most commercial disputes settle. The settlement agreement must say what is released, when the money is paid and what happens to any proceedings.",
{h:"Scope of the release"},
"A release covers only what its words cover. To release claims the parties do not yet know about, the agreement must say so clearly. Fraud is not released by general words.",
{h:"Proceedings"},
"If proceedings have been issued, they are usually stayed by a Tomlin order, with the terms in a confidential schedule. Either side can then go back to court to enforce the terms without starting again.",
{h:"Confidentiality and admissions"},
"Settlements are usually confidential and made without admission of liability.",
{k:"Make the release take effect on payment, not on signing, if you are the party being paid."}],c:["stl-rel"]},
{id:"contract-changes",t:"Varying, ending and assigning contracts",cat:"Foundations",s:"The right document for each change to an existing contract.",b:[
"Contracts change. The document you need depends on what is changing.",
{h:"Variation"},
"To change the terms, both parties sign a variation. If the contract says variations must be in writing and signed, follow that strictly: an informal agreement may not be effective. A deed avoids questions about consideration.",
{h:"Termination by agreement"},
"A deed of termination ends the contract on agreed terms and deals with claims that have already arisen. Decide whether those claims are released.",
{h:"Assignment and novation"},
"Assignment transfers the benefit, such as the right to be paid, and needs written notice to the other party to be a legal assignment. To transfer the obligations as well, all three parties must agree to a novation.",
{k:"Check the original contract first: it may prohibit assignment or require consent."}],c:["dt-rel","da-war"]},
{id:"franchising",t:"Franchising, introducers and sponsorship",cat:"Commercial",s:"Three common ways to grow a business through others, and where they go wrong.",b:[
"Franchising, referral arrangements and sponsorship all let a business reach customers through someone else. Each carries its own risks.",
{h:"Franchising"},
"The franchisor licenses its brand and system and controls how the business is run. Territorial protection and post-term restrictions are the most negotiated points, and both are limited by competition law.",
{h:"Introducers"},
"An introducer passes on leads for a fee. Keep the role limited to introducing, so the introducer does not become a commercial agent with statutory rights to compensation. Make sure the company has anti-bribery procedures that cover introducers.",
{h:"Sponsorship"},
"Sponsors pay for association with an event or brand. Category exclusivity, delivery of the rights, cancellation and reputation clauses carry the risk.",
{k:"For any of these, check whether the sector is regulated before agreeing to pay or receive fees."}],c:["fr-terr","fr-post","ref-fee","sp-excl","sp-morals"]},
{id:"employment-exits",t:"Settlement agreements and director appointments",cat:"Employment",s:"Making an employee exit binding, and appointing non-executive directors properly.",b:[
"Employment claims can only be waived in limited ways. A settlement agreement is the usual one.",
{h:"Conditions"},
"The agreement must be in writing, relate to particular claims, and the employee must have received advice from a relevant independent adviser who is named in the agreement and insured. If any condition is missed, the waiver of statutory claims does not work.",
{h:"Tax"},
"Up to £30,000 of a genuine termination payment can be paid tax-free if the conditions are met. Notice pay and contractual payments are taxed as normal.",
{h:"Confidentiality"},
"Confidentiality clauses cannot stop whistleblowing or the reporting of crime, and should say so.",
{h:"Non-executive directors"},
"Non-executives hold an office, not employment. Their appointment letter covers time commitment, fees, conflicts and insurance. They owe the same statutory duties as executive directors.",
{k:"Agree the reference wording as part of the deal. It is often what the employee cares about most."}],c:["es-ref"]}
);

