{
 const ag={}; (function walk(ns){ns.forEach(n=>{if(n.id)ag[n.id]=n;else walk(n.k)})})(TREE);
 const N=(id,n,b,s,k,d,x)=>(ag[id]=A(id,n,b,s,k,d,x));
 N("gtee","Deed of Guarantee and Indemnity","Beneficiary","Guarantor","gtee","A parent company or individual guarantees another party's obligations, with an indemnity.");
 N("heads","Heads of Terms","Buyer","Seller","heads","Non-binding outline of a transaction, with binding exclusivity, confidentiality and costs.");
 N("stl","Settlement Agreement (Commercial Dispute)","Claimant","Defendant","stl","Settles a commercial dispute in return for a payment, with a release and a stay of proceedings.");
 N("dvar","Deed of Variation","Customer","Supplier","dvar","Changes the terms of an existing contract.");
 N("dterm","Deed of Termination and Release","Customer","Supplier","dterm","Ends an existing contract by agreement and deals with accrued claims.");
 N("dassign","Deed of Assignment","Assignee","Assignor","dassign","Transfers the benefit of a contract to a new party, with a notice to the counterparty.");
 N("jv","Joint Venture Agreement","Minority Shareholder","Majority Shareholder","jv","Two parties set up and run a company together, with deadlock and exit provisions.");
 N("omsha","Shareholders' Agreement (Owner-managed Company)","Minority Shareholder","Majority Shareholder","jv","Regulates the relationship between the shareholders of a private company.",{o:["jv-board","sha-res","jv-dead","jv-transfer","*conflict","conf"],sch:[],
  rec:["The Company is a private company limited by shares incorporated in England and Wales, and the parties are its shareholders.","The parties have agreed to regulate the affairs of the Company, and their relationship as its shareholders, on the terms of this Agreement."],
  note:"Owner-managed companies often also need cross-option or life insurance arrangements, and good leaver and bad leaver provisions for shareholders who work in the business."});
 N("sub","Subscription and Investment Agreement","Investor","Company","sub","An investor subscribes for new shares, with warranties, anti-dilution and investor rights.");
 N("sub-seis","Seed Investment Agreement (SEIS/EIS)","Investor","Company","sub","Early-stage subscription for shares qualifying for SEIS or EIS income tax relief.",{o:["*sub-subscr","*sub-compl","inv-war","*eis","*sub-use","*sub-gov","conf"],
  note:"SEIS and EIS shares must be ordinary shares carrying no preferential right to assets on a winding up, so anti-dilution and liquidation preferences need care. Obtain advance assurance from HMRC before the round."});
 N("asa","Advance Subscription Agreement","Investor","Company","asa","Pre-round investment that converts into shares at the next round or a longstop date, designed for SEIS and EIS.");
 N("cla","Convertible Loan Agreement","Lender","Company","cla","A loan that converts into shares at the next funding round, or is repaid at maturity.");
 N("buyback","Share Buyback Agreement","Company","Selling Shareholder","buyback","A private company buys back its own shares from a shareholder out of distributable profits.");
 N("ned","Non-executive Director Appointment","Company","Director","ned","Terms of appointment of a non-executive director.");
 N("empset","Settlement Agreement (Employment)","Employer","Employee","empset","Ends employment on agreed terms and waives the employee's claims.");
 N("fran","Franchise Agreement","Franchisee","Franchisor","fran","Licenses a business system and brand to a franchisee in return for fees.");
 N("spons","Sponsorship Agreement","Sponsor","Rights Holder","spons","A sponsor pays for rights in connection with an event.");
 N("ref","Introducer Agreement","Company","Introducer","ref","An introducer refers prospective customers in return for a fee.");
 N("collab","Collaboration Agreement","Collaborator","Lead Party","collab","Two or more organisations work together on a research or development project.");
 N("dsa","Data Sharing Agreement","Recipient","Discloser","dsa","One controller shares personal data with another for an agreed purpose.");
 N("std-goods","Terms and Conditions for the Supply of Goods","Customer","Supplier","goods","A supplier's standard business terms for selling goods to business customers.",{rec:[],
  note:"Standard terms only apply if they are incorporated: refer to them in quotations and order acknowledgements and make them available before the contract is made. Onerous or unusual terms must be fairly brought to the customer's attention (Interfoto Picture Library v Stiletto Visual Programmes [1987] EWCA Civ 6)."});
 N("std-svc","Terms and Conditions for the Supply of Services","Customer","Supplier","services","A supplier's standard business terms for providing services to business customers.",{rec:[],
  note:"Standard terms only apply if they are incorporated: refer to them in proposals and engagement letters and make them available before the contract is made. Exclusions in standard terms must satisfy the reasonableness test in the Unfair Contract Terms Act 1977."});
 N("subcon","Subcontract Agreement","Contractor","Subcontractor","services","A contractor engages a subcontractor to perform part of its own customer contract.",{o:["*dur","*svc","*flowdown","war-s","pay","ip","ind","lol","conf","dp","fm","tmb","term","asg"],
  rec:["{B} has agreed to provide services to its customer under the Head Contract.","{B} wishes to subcontract part of those services to {S}, and {S} has agreed to provide them, on the terms of this Agreement."],
  note:"Check that the head contract permits subcontracting, and align the subcontractor's liability cap, insurance and termination rights with the contractor's exposure under the head contract."});
 N("igloan","Intra-group Loan Agreement","Borrower","Lender","loan","A loan between companies in the same group.",{TD:"the date falling [five (5)] years after the date of this Agreement",
  note:"Intra-group loans should be on arm's length terms for transfer pricing purposes. Check corporate benefit for the lender and any restrictions in the group's external facilities."});
 N("shloan","Shareholder Loan Agreement","Company","Shareholder","loan","A shareholder lends money to the company it owns.",{TD:"the date falling [three (3)] years after the date of this Agreement",
  note:"Consider whether the loan should be subordinated to external lenders, and whether interest is deductible for the company."});

 const node=(n,ids)=>({n,k:ids.map(i=>ag[i])});
 const cat=(n,branches)=>({n,k:branches});
 const NEW=[
  cat("Commercial",[
   node("Standard terms",["std-goods","std-svc"]),
   node("Goods",["supply","framework","manuf"]),
   node("Services",["msa","consult","psa","facm","mkt","subcon"]),
   node("Routes to market",["dist","resell","agency","fran","ref","spons"]),
   node("Outsourcing",["bpo","ito"]),
   node("Collaboration",["collab"]),
   node("Changing and ending contracts",["dvar","dterm","dassign","stl"])]),
  cat("Corporate and M&A",[
   node("Deal process",["heads","nda-ma"]),
   node("Share and business sales",["spa","spa-earn","apa","bta"]),
   node("Investment and joint ventures",["sub","sub-seis","asa","cla","sha","omsha","jv"]),
   node("Capital and governance",["buyback","ned"]),
   node("Carve-outs and separations",["carve-spa","tsa","rtsa","ltsa","licback","ttml","ipassign","settle","lta"]),
   node("Confidentiality",["nda-1","nda-m"])]),
  cat("Technology and data",[
   node("Software and cloud",["saas","hosting","swlic","dev","support"]),
   node("Data",["dpa","dsa"])]),
  cat("Intellectual property",[node("Licensing",["patlic","tmlic","khlic"])]),
  cat("Finance",[node("Lending",["loan","bridge","igloan","shloan"]),node("Guarantees",["gtee"])]),
  cat("Real estate",[node("Leases",["office","retail","indl"])]),
  cat("Employment",[node("Contracts of employment",["exec","empc"]),node("Exits",["empset"])])];
 const seen=new Set(); NEW.forEach(c=>c.k.forEach(b=>b.k.forEach(x=>{if(!x)throw new Error("missing agreement in tree");seen.add(x.id)})));
 Object.keys(ag).forEach(id=>{if(!seen.has(id))throw new Error("agreement left out of tree: "+id)});
 TREE.splice(0,TREE.length,...NEW);
}
